#!/usr/bin/env node
/**
 * AssetForge MCP - keyless 2D asset generation for the Khotwa project.
 *
 * Transport: MCP stdio (JSON-RPC 2.0, one message per line).
 * Upstream : Pollinations' free anonymous image endpoint.
 * Output   : <project>/khotwa/assets/generated by default (override with
 *            ASSET_FORGE_OUTPUT).
 *
 * No API key, no account, no external process. Files are written atomically
 * and existing assets are never overwritten (a numeric suffix is added).
 *
 * stdout is reserved for MCP messages. All logging goes to stderr.
 */

import { createInterface } from 'node:readline';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = path.resolve(HERE, '..', '..', '..');
const OUTPUT_ROOT = path.resolve(
  process.env.ASSET_FORGE_OUTPUT || path.join(PROJECT_ROOT, 'khotwa', 'assets', 'generated'),
);
const IMAGE_ENDPOINT = 'https://image.pollinations.ai/prompt/';
const REQUEST_TIMEOUT_MS = Number(process.env.ASSET_FORGE_TIMEOUT_MS || 180000);
const MODEL = process.env.ASSET_FORGE_MODEL || 'flux';
const SERVER_VERSION = '1.0.0';

const STYLE_HINTS = {
  'flat-vector': 'clean flat vector 2D game art, bold readable shapes, crisp edges, centered composition, no text, no watermark',
  'pixel-art': '16-bit pixel art, limited palette, crisp pixels, centered composition, no text, no watermark',
  'hand-painted': 'hand-painted 2D game art, rich colors, soft shading, centered composition, no text, no watermark',
  cartoon: 'cartoon 2D game art, thick outlines, vibrant colors, centered composition, no text, no watermark',
};

const BACKGROUND_HINTS = {
  auto: '',
  white: 'on a plain solid white background',
  black: 'on a plain solid black background',
  'green-screen': 'on a flat chroma-key green (#00FF00) background',
};

let stdinClosed = false;

function log(...args) {
  process.stderr.write(`[assetforge] ${args.join(' ')}\n`);
}

function send(message) {
  if (stdinClosed) return;
  process.stdout.write(`${JSON.stringify(message)}\n`);
}

function ok(id, result) {
  send({ jsonrpc: '2.0', id, result });
}

function fail(id, code, message, data) {
  send({ jsonrpc: '2.0', id, error: { code, message, ...(data === undefined ? {} : { data }) } });
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function slugify(value) {
  const slug = String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64);
  if (!slug) throw new Error('name must contain at least one letter or digit');
  return slug;
}

function clampInt(value, fallback, min, max, label) {
  if (value === undefined || value === null || value === '') return fallback;
  const number = Number(value);
  if (!Number.isFinite(number) || Math.round(number) !== number) {
    throw new Error(`${label} must be an integer`);
  }
  if (number < min || number > max) throw new Error(`${label} must be between ${min} and ${max}`);
  return number;
}

function styleHint(style) {
  return STYLE_HINTS[style] || STYLE_HINTS['flat-vector'];
}

function buildPrompt(prompt, style, background) {
  const extra = [styleHint(style)];
  const bg = BACKGROUND_HINTS[background];
  if (bg) extra.push(bg);
  return `${prompt}. ${extra.join(', ')}.`;
}

async function uniqueTarget(kind, name, extension) {
  const dir = path.join(OUTPUT_ROOT, kind);
  await fs.mkdir(dir, { recursive: true });
  const base = slugify(name);
  let candidate = path.join(dir, `${base}${extension}`);
  for (let index = 2; index < 1000; index += 1) {
    try {
      await fs.access(candidate);
      candidate = path.join(dir, `${base}-${index}${extension}`);
    } catch {
      break;
    }
  }
  const resolved = path.resolve(candidate);
  if (!resolved.startsWith(`${OUTPUT_ROOT}${path.sep}`)) {
    throw new Error('refusing to write outside the asset output directory');
  }
  return resolved;
}

const EXTENSIONS = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'image/webp': '.webp',
  'image/gif': '.gif',
};

class RetryableError extends Error {}

async function fetchImage(url) {
  let lastError = null;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      const response = await fetch(url, {
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        headers: { 'user-agent': `assetforge-mcp/${SERVER_VERSION}` },
      });
      if (!response.ok) {
        const body = await response.text().catch(() => '');
        const message = `image service returned HTTP ${response.status}${body ? `: ${body.slice(0, 200)}` : ''}`;
        if (response.status === 429 || response.status >= 500) throw new RetryableError(message);
        throw new Error(message);
      }
      const type = (response.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
      if (!type.startsWith('image/')) {
        throw new Error(`expected an image response, received ${type || 'no content type'}`);
      }
      const buffer = Buffer.from(await response.arrayBuffer());
      if (buffer.length < 1024) throw new Error('generated image was too small to be valid');
      if (buffer.length > 25 * 1024 * 1024) throw new Error('generated image exceeded 25 MB');
      return { buffer, type };
    } catch (error) {
      lastError = error;
      const retryable = error instanceof RetryableError || error.name === 'TimeoutError' || error.name === 'AbortError';
      if (!retryable || attempt === 3) break;
      log(`attempt ${attempt} failed (${error.message}); retrying`);
      await sleep(attempt * 3000);
    }
  }
  throw lastError;
}

// Serialise generations so the free endpoint is not hit concurrently.
let generationQueue = Promise.resolve();
function enqueue(task) {
  const run = generationQueue.then(task, task);
  generationQueue = run.then(() => undefined, () => undefined);
  return run;
}

async function generate({ prompt, name, width, height, seed, style, background, kind, prefix }) {
  if (typeof prompt !== 'string' || !prompt.trim()) throw new Error('prompt is required');
  if (prompt.length > 1500) throw new Error('prompt must be 1500 characters or fewer');
  const finalPrompt = buildPrompt(`${prefix}${prompt.trim()}`, style, background);
  const url = new URL(`${IMAGE_ENDPOINT}${encodeURIComponent(finalPrompt)}`);
  url.searchParams.set('width', String(width));
  url.searchParams.set('height', String(height));
  url.searchParams.set('model', MODEL);
  url.searchParams.set('nologo', 'true');
  if (seed !== undefined) url.searchParams.set('seed', String(seed));

  log(`generating ${kind}/${name} at ${width}x${height}`);
  const started = Date.now();
  const { buffer, type } = await fetchImage(url);
  const extension = EXTENSIONS[type] || '.png';
  const target = await uniqueTarget(kind, name, extension);
  const temporary = `${target}.part`;
  await fs.writeFile(temporary, buffer);
  await fs.rename(temporary, target);
  const relative = path.relative(PROJECT_ROOT, target).split(path.sep).join('/');
  const result = {
    ok: true,
    path: target,
    project_path: relative,
    bytes: buffer.length,
    width,
    height,
    kind,
    prompt: finalPrompt,
    seed: seed === undefined ? null : seed,
    seconds: Math.round((Date.now() - started) / 100) / 10,
  };
  log(`wrote ${relative} (${buffer.length} bytes)`);
  return result;
}

async function listAssets(kind) {
  const kinds = kind && kind !== 'all' ? [kind] : ['sprites', 'backgrounds', 'ui'];
  const assets = [];
  for (const folder of kinds) {
    if (!['sprites', 'backgrounds', 'ui'].includes(folder)) throw new Error(`unknown kind "${folder}"`);
    const dir = path.join(OUTPUT_ROOT, folder);
    let entries = [];
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      if (!entry.isFile() || entry.name.endsWith('.part')) continue;
      const full = path.join(dir, entry.name);
      const stat = await fs.stat(full);
      assets.push({
        kind: folder,
        name: entry.name,
        path: full,
        project_path: path.relative(PROJECT_ROOT, full).split(path.sep).join('/'),
        bytes: stat.size,
        modified: stat.mtime.toISOString(),
      });
    }
  }
  assets.sort((a, b) => a.project_path.localeCompare(b.project_path));
  return { ok: true, output_root: OUTPUT_ROOT, count: assets.length, assets };
}

async function status() {
  const listing = await listAssets('all');
  return {
    ok: true,
    server: 'assetforge',
    version: SERVER_VERSION,
    output_root: OUTPUT_ROOT,
    endpoint: IMAGE_ENDPOINT,
    model: MODEL,
    key_required: false,
    assets: listing.count,
  };
}

const TOOLS = [
  {
    name: 'generate_sprite',
    description:
      'Generate one 2D game sprite (character, obstacle, pickup, coin, prop) from a text prompt and save it as an image file. Returns the absolute file path. Never overwrites an existing asset.',
    inputSchema: {
      type: 'object',
      properties: {
        prompt: { type: 'string', description: 'What to draw, e.g. "a small orange fox courier, side view, running pose".' },
        name: { type: 'string', description: 'File name without extension, e.g. "fox-run-01".' },
        width: { type: 'integer', minimum: 32, maximum: 2048, default: 256 },
        height: { type: 'integer', minimum: 32, maximum: 2048, default: 256 },
        seed: { type: 'integer', minimum: 0, maximum: 2147483647, description: 'Optional seed for reproducible output.' },
        style: { type: 'string', enum: Object.keys(STYLE_HINTS), default: 'flat-vector' },
        background: { type: 'string', enum: Object.keys(BACKGROUND_HINTS), default: 'auto' },
      },
      required: ['prompt', 'name'],
      additionalProperties: false,
    },
  },
  {
    name: 'generate_background',
    description:
      'Generate a wide 2D side-scrolling level or menu background and save it as an image file. Returns the absolute file path. Never overwrites an existing asset.',
    inputSchema: {
      type: 'object',
      properties: {
        prompt: { type: 'string', description: 'Scene description, e.g. "a warm desert railway at sunset".' },
        name: { type: 'string', description: 'File name without extension.' },
        width: { type: 'integer', minimum: 320, maximum: 4096, default: 1920 },
        height: { type: 'integer', minimum: 240, maximum: 4096, default: 1080 },
        seed: { type: 'integer', minimum: 0, maximum: 2147483647 },
        style: { type: 'string', enum: Object.keys(STYLE_HINTS), default: 'hand-painted' },
      },
      required: ['prompt', 'name'],
      additionalProperties: false,
    },
  },
  {
    name: 'generate_ui_icon',
    description:
      'Generate a single game UI icon (coin, heart, pause, sound, revive) and save it as an image file. Returns the absolute file path. Never overwrites an existing asset.',
    inputSchema: {
      type: 'object',
      properties: {
        prompt: { type: 'string', description: 'Icon subject, e.g. "a shiny gold coin".' },
        name: { type: 'string', description: 'File name without extension.' },
        size: { type: 'integer', minimum: 32, maximum: 1024, default: 128 },
        seed: { type: 'integer', minimum: 0, maximum: 2147483647 },
        style: { type: 'string', enum: Object.keys(STYLE_HINTS), default: 'flat-vector' },
      },
      required: ['prompt', 'name'],
      additionalProperties: false,
    },
  },
  {
    name: 'list_generated_assets',
    description: 'List image files previously generated by this server, with absolute paths and sizes.',
    inputSchema: {
      type: 'object',
      properties: {
        kind: { type: 'string', enum: ['all', 'sprites', 'backgrounds', 'ui'], default: 'all' },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'status',
    description: 'Report the output directory, upstream model, and number of generated assets. Makes no network request.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
  },
];

async function callTool(name, args = {}) {
  switch (name) {
    case 'generate_sprite':
      return generate({
        prompt: args.prompt,
        name: args.name,
        width: clampInt(args.width, 256, 32, 2048, 'width'),
        height: clampInt(args.height, 256, 32, 2048, 'height'),
        seed: args.seed === undefined ? undefined : clampInt(args.seed, 0, 0, 2147483647, 'seed'),
        style: args.style,
        background: args.background,
        kind: 'sprites',
        prefix: '2D game sprite: ',
      });
    case 'generate_background':
      return generate({
        prompt: args.prompt,
        name: args.name,
        width: clampInt(args.width, 1920, 320, 4096, 'width'),
        height: clampInt(args.height, 1080, 240, 4096, 'height'),
        seed: args.seed === undefined ? undefined : clampInt(args.seed, 0, 0, 2147483647, 'seed'),
        style: args.style || 'hand-painted',
        background: 'auto',
        kind: 'backgrounds',
        prefix: 'wide side-scrolling 2D game background, no text, no characters: ',
      });
    case 'generate_ui_icon':
      return generate({
        prompt: args.prompt,
        name: args.name,
        width: clampInt(args.size, 128, 32, 1024, 'size'),
        height: clampInt(args.size, 128, 32, 1024, 'size'),
        seed: args.seed === undefined ? undefined : clampInt(args.seed, 0, 0, 2147483647, 'seed'),
        style: args.style,
        background: 'auto',
        kind: 'ui',
        prefix: 'single centered game UI icon: ',
      });
    case 'list_generated_assets':
      return listAssets(args.kind || 'all');
    case 'assetforge_status':
    case 'status':
      return status();
    default:
      throw new Error(`unknown tool "${name}"`);
  }
}

async function handle(message) {
  const { id, method, params } = message;
  const isNotification = id === undefined || id === null;

  try {
    if (method === 'initialize') {
      ok(id, {
        protocolVersion: params?.protocolVersion || '2025-06-18',
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: 'assetforge', version: SERVER_VERSION },
        instructions:
          `AssetForge generates keyless 2D art for the Khotwa game and saves every file under ${OUTPUT_ROOT}. ` +
          'Use generate_sprite for characters, obstacles, pickups and props; generate_background for 1920x1080 level art; ' +
          'generate_ui_icon for HUD icons. Always report the returned absolute path. Existing assets are never overwritten.',
      });
      return;
    }
    if (isNotification) return;

    switch (method) {
      case 'ping':
        ok(id, {});
        return;
      case 'tools/list':
        ok(id, { tools: TOOLS });
        return;
      case 'tools/call': {
        const toolName = params?.name;
        try {
          const result = await enqueue(() => callTool(toolName, params?.arguments || {}));
          ok(id, { content: [{ type: 'text', text: JSON.stringify(result, null, 2) }] });
        } catch (error) {
          log(`tool ${toolName} failed: ${error.message}`);
          ok(id, {
            content: [{ type: 'text', text: `AssetForge error: ${error.message}` }],
            isError: true,
          });
        }
        return;
      }
      case 'resources/list':
        ok(id, { resources: [] });
        return;
      case 'resources/templates/list':
        ok(id, { resourceTemplates: [] });
        return;
      case 'prompts/list':
        ok(id, { prompts: [] });
        return;
      default:
        fail(id, -32601, `method not found: ${method}`);
    }
  } catch (error) {
    if (!isNotification) fail(id, -32603, `internal error: ${error.message}`);
  }
}

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
rl.on('line', (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;
  let message;
  try {
    message = JSON.parse(trimmed);
  } catch {
    send({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'parse error' } });
    return;
  }
  void handle(message);
});

rl.on('close', () => {
  stdinClosed = true;
  process.stdout.write('', () => process.exit(0));
});

log(`ready; output=${OUTPUT_ROOT}; model=${MODEL}`);
